CREATE TABLE account_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE accounts(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,client_id TEXT UNIQUE NOT NULL,state_version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE agent_goal_steps(id INTEGER PRIMARY KEY,goal_id INTEGER,step_no INTEGER,tool TEXT,args TEXT,result TEXT,state TEXT DEFAULT 'planned',expected_observation TEXT,created_at TEXT,finished_at TEXT,UNIQUE(goal_id,step_no),FOREIGN KEY(goal_id) REFERENCES agent_goals(id));
CREATE TABLE agent_goals(id INTEGER PRIMARY KEY,user_id INTEGER,client_id TEXT,objective TEXT,success_criteria TEXT,state TEXT DEFAULT 'running',current_step INTEGER DEFAULT 0,max_steps INTEGER DEFAULT 6,last_observation TEXT DEFAULT '',created_at TEXT,updated_at TEXT,completed_at TEXT);
CREATE TABLE agent_logs(id INTEGER PRIMARY KEY,client_id TEXT,kind TEXT,detail TEXT,created_at TEXT);
CREATE TABLE agent_memory(id INTEGER PRIMARY KEY,user_id INTEGER,kind TEXT,date TEXT,payload TEXT,created_at TEXT);
CREATE TABLE agent_tasks(id INTEGER PRIMARY KEY,user_id INTEGER,kind TEXT,due_date TEXT,status TEXT DEFAULT 'pending',payload TEXT,created_at TEXT, priority INTEGER DEFAULT 0, state TEXT DEFAULT 'pending', due_at TEXT, goal_id INTEGER, dependencies TEXT);
CREATE TABLE aliases(id INTEGER PRIMARY KEY,food_id INTEGER,alias TEXT UNIQUE,FOREIGN KEY(food_id) REFERENCES foods(id));
CREATE TABLE auth_attempts(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE candidates(id INTEGER PRIMARY KEY,name TEXT,payload TEXT,source_url TEXT,status TEXT DEFAULT 'pending_review',created_at TEXT);
CREATE TABLE foods(id INTEGER PRIMARY KEY,name TEXT UNIQUE,category TEXT,kcal REAL,protein REAL,fat REAL,carbs REAL,source TEXT,source_url TEXT,source_id TEXT,confidence TEXT,status TEXT DEFAULT 'verified',updated_at TEXT);
CREATE TABLE goals(id INTEGER PRIMARY KEY,user_id INTEGER,kind TEXT,start_value REAL,current_value REAL,target_value REAL,deadline TEXT,status TEXT DEFAULT 'active',created_at TEXT,updated_at TEXT);
CREATE TABLE meal_logs(id INTEGER PRIMARY KEY,user_id INTEGER,date TEXT,type TEXT,name TEXT,calories REAL,protein REAL,source TEXT,recorded_at TEXT, details TEXT DEFAULT '{}');
CREATE TABLE memory_embeddings(id INTEGER PRIMARY KEY,memory_id INTEGER,embedding TEXT);
CREATE TABLE skill_embeddings(id INTEGER PRIMARY KEY,skill_id INTEGER,embedding TEXT);
CREATE TABLE skills(id INTEGER PRIMARY KEY,user_id INTEGER,name TEXT,description TEXT,schema TEXT,preconditions TEXT,fallback TEXT,steps TEXT,version INTEGER DEFAULT 1,scope TEXT DEFAULT 'user',source TEXT DEFAULT 'agent',active INTEGER DEFAULT 1,created_at TEXT,updated_at TEXT,UNIQUE(user_id,name));
CREATE TABLE users(id INTEGER PRIMARY KEY,client_id TEXT UNIQUE,profile TEXT,chat_history TEXT,pending_meal TEXT,budget_adjustment_kcal INTEGER DEFAULT 0,created_at TEXT,updated_at TEXT, app_state TEXT DEFAULT '{}');
CREATE TABLE weight_logs(id INTEGER PRIMARY KEY,user_id INTEGER,date TEXT,weight REAL,source TEXT,recorded_at TEXT,UNIQUE(user_id,date));
CREATE TABLE write_guards(ok INTEGER NOT NULL CHECK(ok=1));
CREATE INDEX account_session_owner ON account_sessions(account_id);
CREATE INDEX IF NOT EXISTS meal_logs_owner ON meal_logs(user_id);
CREATE INDEX IF NOT EXISTS weight_logs_owner ON weight_logs(user_id);
CREATE INDEX IF NOT EXISTS agent_memory_owner ON agent_memory(user_id);
CREATE INDEX IF NOT EXISTS agent_tasks_owner ON agent_tasks(user_id);
CREATE INDEX IF NOT EXISTS goals_owner ON goals(user_id);
CREATE INDEX IF NOT EXISTS skills_owner ON skills(user_id);
CREATE INDEX IF NOT EXISTS agent_goals_owner ON agent_goals(user_id);
CREATE INDEX IF NOT EXISTS agent_logs_owner ON agent_logs(client_id);
CREATE INDEX IF NOT EXISTS session_expiry ON account_sessions(expires_at);
CREATE INDEX IF NOT EXISTS auth_expiry ON auth_attempts(expires_at);
